import re
from datetime import datetime, timezone

_DEFAULT_PROFILE = (5, 8.0, 30.0)

_PROFILES = {
    "catalog": (6, 8.0, 30.0),
    "auth": (6, 6.0, 20.0),
    "payments": (3, 1.0, 30.0),
    "ledger": (8, 3.0, 60.0),
    "ledger-export": (4, 8.0, 10.0),
    "reports": (9, 5.0, 120.0),
    "inventory": (7, 4.0, 90.0),
    "search": (10, 12.0, 45.0),
    "shipping": (8, 3.0, 40.0),
    "media": (5, 8.0, 15.0),
}

_RETRYABLE_STATUSES = {429, 502, 503, 504}
_IDEMPOTENT_METHODS = {"GET", "HEAD", "OPTIONS", "PUT", "DELETE"}
_UNSAFE_METHODS = {"POST", "PATCH"}
_MONTHS = {
    name: number
    for number, name in enumerate(
        "Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec".split(), start=1
    )
}
_DAYS = {"Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"}
_HTTP_DATE = re.compile(
    r"([A-Za-z]{3}), ([0-9]{2}) ([A-Za-z]{3}) ([0-9]{4}) "
    r"([0-9]{2}):([0-9]{2}):([0-9]{2}) GMT"
)


def _header(headers: dict[str, str], name: str) -> str | None:
    for key, value in (headers or {}).items():
        if key.lower() == name:
            return value
    return None


def _retry_after_seconds(value: str | None, now: datetime) -> float | None:
    if value is None:
        return None
    text = value.strip(" \t")
    if re.fullmatch(r"[0-9]+", text):
        return float(int(text))
    match = _HTTP_DATE.fullmatch(text)
    if not match:
        return None
    day_name, day, month_name, year, hour, minute, second = match.groups()
    if day_name not in _DAYS or month_name not in _MONTHS:
        return None
    try:
        moment = datetime(
            int(year),
            _MONTHS[month_name],
            int(day),
            int(hour),
            int(minute),
            int(second),
            tzinfo=timezone.utc,
        )
    except ValueError:
        return None
    return max(0.0, (moment - now).total_seconds())


def retry_delay(
    method: str,
    request_headers: dict[str, str],
    attempt: int,
    status: int | None,
    response_headers: dict[str, str],
    now: datetime,
) -> float | None:
    """Seconds to wait before the next attempt, or None to give up.

    `attempt` is the number of the attempt that just failed, 1 for the first.
    `status` is None when there was no response (a connection error).
    `now` is the current time, timezone-aware UTC.
    """
    if status is not None and status not in _RETRYABLE_STATUSES:
        return None

    verb = method.strip().upper()
    if verb in _UNSAFE_METHODS:
        key = _header(request_headers, "idempotency-key")
        if key is None or not key.strip():
            return None
    elif verb not in _IDEMPOTENT_METHODS:
        return None

    service = (_header(request_headers, "x-service") or "").strip().lower()
    max_attempts, cap, max_retry_after = _PROFILES.get(service, _DEFAULT_PROFILE)

    if attempt >= max_attempts:
        return None

    delay = min(cap, 0.25 * 2 ** min(max(attempt - 1, 0), 60))

    if status in (429, 503):
        wait = _retry_after_seconds(_header(response_headers, "retry-after"), now)
        if wait is not None:
            if wait > max_retry_after:
                return None
            delay = max(delay, wait)

    return float(delay)
EOF
